//! Tokio-backed executor ABI for async frames generated by the compiler.

pub use crate::abi::{TyrusAsyncDropFrame, TyrusAsyncPoll};
use crate::{
    TYRUS_PROMISE_FULFILLED, TYRUS_PROMISE_PENDING, TyrusPromise, tyrus_promise_cancel_pending,
    tyrus_promise_free, tyrus_promise_on_settle, tyrus_promise_retain, tyrus_promise_state,
    wait_until_settled,
};
use std::ffi::c_void;
use std::sync::atomic::{AtomicBool, AtomicU8, AtomicUsize, Ordering};
use std::sync::{Arc, OnceLock, Weak};
use tokio::runtime::{Builder, Runtime};
use tyrus_string::TyrusString;

pub const TYRUS_ASYNC_PENDING: i32 = 0;
pub const TYRUS_ASYNC_READY: i32 = 1;

const TASK_IDLE: u8 = 0;
const TASK_SCHEDULED: u8 = 1;
const TASK_POLLING: u8 = 2;
const TASK_NOTIFIED: u8 = 3;
const TASK_COMPLETE: u8 = 4;

pub const WORKER_THREADS_ENV: &str = "TYRUS_WORKER_THREADS";

pub const REPORT_PENDING_TASKS_ENV: &str = "TYRUS_REPORT_PENDING_TASKS";

type TyrusBlockingCallback = unsafe extern "C" fn(*mut c_void, *mut TyrusPromise);
type TyrusBlockingContextDrop = unsafe extern "C" fn(*mut c_void);

static EXECUTOR: OnceLock<Runtime> = OnceLock::new();

static CONFIGURED_WORKER_THREADS: AtomicUsize = AtomicUsize::new(0);

static LIVE_TASKS: AtomicUsize = AtomicUsize::new(0);

static ACTIVE_POLLS: AtomicUsize = AtomicUsize::new(0);

struct ActivePoll;

impl Drop for ActivePoll {
    fn drop(&mut self) {
        ACTIVE_POLLS.fetch_sub(1, Ordering::AcqRel);
    }
}

#[unsafe(no_mangle)]
pub extern "C" fn tyrus_runtime_configure_worker_threads(threads: u64) {
    CONFIGURED_WORKER_THREADS.store(threads as usize, Ordering::Relaxed);
}

fn detected_parallelism() -> usize {
    std::thread::available_parallelism().map_or(1, std::num::NonZero::get)
}

fn resolve_worker_threads() -> usize {
    let detected = detected_parallelism();
    let (requested, source) = match std::env::var(WORKER_THREADS_ENV) {
        Ok(raw) => match raw.trim().parse::<usize>() {
            Ok(0) | Err(_) => {
                eprintln!(
                    "tyrus runtime warning: ignoring {WORKER_THREADS_ENV}={raw:?}, which is not a positive integer; using {detected} worker threads"
                );
                return detected;
            }
            Ok(threads) => (threads, WORKER_THREADS_ENV),
        },
        Err(_) => match CONFIGURED_WORKER_THREADS.load(Ordering::Relaxed) {
            0 => return detected,
            threads => (threads, "runtime.workerThreads"),
        },
    };

    if requested > detected * 2 {
        eprintln!(
            "tyrus runtime warning: {source} requests {requested} worker threads, but only {detected} logical CPUs were detected"
        );
    }
    requested
}

pub(crate) fn executor() -> &'static Runtime {
    EXECUTOR.get_or_init(|| {
        Builder::new_multi_thread()
            .worker_threads(resolve_worker_threads())
            .enable_all()
            .thread_name("tyrus-async")
            .build()
            .unwrap_or_else(|error| panic!("failed to initialize tyrus async runtime: {error}"))
    })
}

#[unsafe(no_mangle)]
pub extern "C" fn tyrus_runtime_pending_tasks() -> u64 {
    LIVE_TASKS.load(Ordering::Acquire) as u64
}

/// Schedules a synchronous native callback on the runtime's blocking pool.
///
/// # Safety
///
/// `callback` must be a valid generated-code function for the process lifetime.
/// `context` must remain valid until `drop_context` runs, and both callbacks
/// must obey the native ABI and must not unwind across it.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn tyrus_spawn_blocking(
    callback: Option<TyrusBlockingCallback>,
    context: *mut c_void,
    drop_context: Option<TyrusBlockingContextDrop>,
) -> *mut TyrusPromise {
    let promise = crate::tyrus_promise_pending();
    let Some(callback) = callback else {
        unsafe {
            crate::tyrus_promise_reject_pending(
                promise,
                TyrusString::literal("database blocking callback is unavailable"),
            );
            if let Some(drop_context) = drop_context {
                drop_context(context);
            }
        }
        return promise;
    };
    unsafe { crate::tyrus_promise_retain(promise) };
    let promise_address = promise as usize;
    let context_address = context as usize;
    executor().spawn_blocking(move || {
        let promise = promise_address as *mut TyrusPromise;
        let context = context_address as *mut c_void;
        unsafe {
            callback(context, promise);
            if crate::tyrus_promise_state(promise) == TYRUS_PROMISE_PENDING {
                crate::tyrus_promise_reject_pending(
                    promise,
                    TyrusString::literal("blocking callback returned without settling its Promise"),
                );
            }
            if let Some(drop_context) = drop_context {
                drop_context(context);
            }
            crate::tyrus_promise_free(promise);
        }
    });
    promise
}

#[unsafe(no_mangle)]
pub extern "C" fn tyrus_runtime_shutdown() {
    let mut pending = LIVE_TASKS.load(Ordering::Acquire);
    let deadline = std::time::Instant::now() + std::time::Duration::from_millis(5);
    while pending > 0 && std::time::Instant::now() < deadline {
        std::thread::yield_now();
        pending = LIVE_TASKS.load(Ordering::Acquire);
    }
    if pending > 0 && reports_pending_tasks() {
        let plural = if pending == 1 { "task" } else { "tasks" };
        eprintln!(
            "tyrus runtime: {pending} asynchronous {plural} still pending when `main` finished; cancelled without completing"
        );
    }

    let poll_deadline = std::time::Instant::now() + std::time::Duration::from_millis(50);
    while ACTIVE_POLLS.load(Ordering::Acquire) > 0 && std::time::Instant::now() < poll_deadline {
        std::thread::yield_now();
    }
    crate::http::wait_for_servers();
    crate::db::shutdown();
}

fn reports_pending_tasks() -> bool {
    std::env::var(REPORT_PENDING_TASKS_ENV).is_ok_and(|value| matches!(value.trim(), "1" | "true"))
}

pub(crate) fn schedule_runtime_callback(
    callback: unsafe extern "C" fn(*mut c_void),
    context: *mut c_void,
) {
    let context = context as usize;
    executor().spawn(async move {
        unsafe { callback(context as *mut c_void) };
    });
}

pub(crate) struct PromiseTaskOwner {
    pub(crate) promise: usize,
}

impl Drop for PromiseTaskOwner {
    fn drop(&mut self) {
        unsafe { tyrus_promise_free(self.promise as *mut TyrusPromise) };
    }
}

impl PromiseTaskOwner {
    /// Settles the promise while this task still owns its retained reference.
    ///
    /// Reading `self.promise` into a local allowed non-lexical lifetimes to
    /// drop the guard before the native call. If the caller had released its
    /// handle meanwhile, the completion path then dereferenced freed memory.
    pub(crate) unsafe fn fulfill_void(&self) {
        unsafe {
            crate::tyrus_promise_fulfill(
                self.promise as *mut TyrusPromise,
                std::ptr::null_mut(),
                None,
            );
        }
    }

    /// Rejects the promise with a stable code and a readable message, under the
    /// same ownership discipline as `fulfill_void`.
    ///
    /// Both strings must be static: this is a failure path, and a message
    /// formatted at the moment of failure is a message that can fail to be
    /// produced.
    pub(crate) unsafe fn reject_structured(&self, code: &'static str, message: &'static str) {
        unsafe {
            crate::tyrus_promise_reject_pending_structured(
                self.promise as *mut TyrusPromise,
                tyrus_string::TyrusString::literal(code),
                tyrus_string::TyrusString::literal(message),
            );
        }
    }
}

#[repr(C)]
pub struct TyrusAsyncTask {
    poll: TyrusAsyncPoll,
    drop_frame: TyrusAsyncDropFrame,
    frame: *mut c_void,
    result: *mut TyrusPromise,
    dependency: std::sync::Mutex<*mut TyrusPromise>,
    state: AtomicU8,
    interrupted: AtomicBool,
}

impl TyrusAsyncTask {
    unsafe fn set_dependency(&self, dependency: *mut TyrusPromise) {
        unsafe {
            let replaced = {
                let mut slot = match self.dependency.lock() {
                    Ok(slot) => slot,
                    Err(poisoned) => poisoned.into_inner(),
                };
                if !dependency.is_null() {
                    tyrus_promise_retain(dependency);
                }
                std::mem::replace(&mut *slot, dependency)
            };
            if !replaced.is_null() {
                tyrus_promise_free(replaced);
            }
        }
    }

    unsafe fn take_dependency(&self) -> *mut TyrusPromise {
        let mut slot = match self.dependency.lock() {
            Ok(slot) => slot,
            Err(poisoned) => poisoned.into_inner(),
        };
        std::mem::replace(&mut *slot, std::ptr::null_mut())
    }

    unsafe fn dependency_reference(&self) -> *mut TyrusPromise {
        unsafe {
            let slot = match self.dependency.lock() {
                Ok(slot) => slot,
                Err(poisoned) => poisoned.into_inner(),
            };
            if slot.is_null() {
                return std::ptr::null_mut();
            }
            tyrus_promise_retain(*slot)
        }
    }
}

unsafe impl Send for TyrusAsyncTask {}
unsafe impl Sync for TyrusAsyncTask {}

impl Drop for TyrusAsyncTask {
    fn drop(&mut self) {
        if self.state.swap(TASK_COMPLETE, Ordering::AcqRel) != TASK_COMPLETE {
            LIVE_TASKS.fetch_sub(1, Ordering::AcqRel);
        }
        unsafe {
            let dependency = self.take_dependency();
            if !dependency.is_null() {
                tyrus_promise_cancel_pending(
                    dependency,
                    TyrusString::literal("async task was cancelled"),
                );
                tyrus_promise_free(dependency);
            }
            if let Some(drop_frame) = self.drop_frame {
                drop_frame(self.frame);
            }
            tyrus_promise_free(self.result);
        }
    }
}

unsafe fn task_ref<'a>(task: *const TyrusAsyncTask) -> &'a TyrusAsyncTask {
    unsafe {
        if task.is_null() {
            crate::panic::abort_with(TyrusString::null(), "tyrus runtime error: null async task");
        }
        &*task
    }
}

fn enqueue(task: *mut TyrusAsyncTask) {
    unsafe { Arc::increment_strong_count(task) };
    ACTIVE_POLLS.fetch_add(1, Ordering::AcqRel);
    let address = task as usize;
    executor().spawn(async move {
        let _active = ActivePoll;
        let task_ptr = address as *mut TyrusAsyncTask;
        let task = unsafe { task_ref(task_ptr) };
        task.state.store(TASK_POLLING, Ordering::Release);
        if unsafe { tyrus_promise_state(task.result) } != TYRUS_PROMISE_PENDING {
            if task.state.swap(TASK_COMPLETE, Ordering::AcqRel) != TASK_COMPLETE {
                LIVE_TASKS.fetch_sub(1, Ordering::AcqRel);
            }
            unsafe { Arc::decrement_strong_count(task_ptr) };
            return;
        }
        let status = unsafe { (task.poll)(task.frame, task.result, task_ptr) };
        if status == TYRUS_ASYNC_READY {
            if task.state.swap(TASK_COMPLETE, Ordering::AcqRel) != TASK_COMPLETE {
                LIVE_TASKS.fetch_sub(1, Ordering::AcqRel);
            }
        } else {
            let previous = task.state.swap(TASK_IDLE, Ordering::AcqRel);
            if previous == TASK_NOTIFIED {
                schedule(task_ptr);
            }
        }
        unsafe { Arc::decrement_strong_count(task_ptr) };
    });
}

fn schedule(task: *mut TyrusAsyncTask) {
    let task_ref = unsafe { task_ref(task) };
    loop {
        match task_ref.state.load(Ordering::Acquire) {
            TASK_IDLE => {
                if task_ref
                    .state
                    .compare_exchange(
                        TASK_IDLE,
                        TASK_SCHEDULED,
                        Ordering::AcqRel,
                        Ordering::Acquire,
                    )
                    .is_ok()
                {
                    enqueue(task);
                    return;
                }
            }
            TASK_POLLING => {
                let _ = task_ref.state.compare_exchange(
                    TASK_POLLING,
                    TASK_NOTIFIED,
                    Ordering::AcqRel,
                    Ordering::Acquire,
                );
                return;
            }
            TASK_SCHEDULED | TASK_NOTIFIED | TASK_COMPLETE => return,
            _ => unreachable!("invalid async task state"),
        }
    }
}

/// Create an executor task for a compiler-generated async frame.
///
/// The task retains `result` until the task and all waiter-owned references are released.
///
/// # Safety
///
/// All pointers and callbacks must follow the compiler/runtime async ABI.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn tyrus_async_task_new(
    poll: TyrusAsyncPoll,
    drop_frame: TyrusAsyncDropFrame,
    frame: *mut c_void,
    result: *mut TyrusPromise,
) -> *mut TyrusAsyncTask {
    unsafe {
        tyrus_promise_retain(result);
        LIVE_TASKS.fetch_add(1, Ordering::AcqRel);
        let task = Arc::new(TyrusAsyncTask {
            poll,
            drop_frame,
            frame,
            result,
            dependency: std::sync::Mutex::new(std::ptr::null_mut()),
            state: AtomicU8::new(TASK_IDLE),
            interrupted: AtomicBool::new(false),
        });
        let result_context = Arc::into_raw(task.clone()).cast_mut().cast();
        tyrus_promise_on_settle(
            result,
            Some(tyrus_async_task_result_settled),
            result_context,
        );
        let cancel_context = Box::new(TaskCancelRequest {
            task: Arc::downgrade(&task),
        });
        crate::tyrus_promise_on_cancel_request(
            result,
            tyrus_async_task_cancel_requested,
            Box::into_raw(cancel_context).cast(),
            Some(drop_task_cancel_request),
        );
        Arc::into_raw(task).cast_mut()
    }
}

struct TaskCancelRequest {
    task: Weak<TyrusAsyncTask>,
}

unsafe extern "C" fn drop_task_cancel_request(context: *mut c_void) {
    unsafe {
        drop(Box::from_raw(context.cast::<TaskCancelRequest>()));
    }
}

unsafe extern "C" fn tyrus_async_task_cancel_requested(context: *mut c_void) {
    unsafe {
        let context = &*context.cast::<TaskCancelRequest>();
        let Some(task) = context.task.upgrade() else {
            return;
        };
        let dependency = task.dependency_reference();
        if !dependency.is_null() {
            if !task.interrupted.swap(true, Ordering::AcqRel) {
                crate::tyrus_promise_request_cancel(
                    dependency,
                    TyrusString::literal("the awaiting task was cancelled"),
                );
            }
            tyrus_promise_free(dependency);
        } else {
            // A pending dependency schedules this task when its cancellation
            // settles. Polling before that would return READY without settling
            // the task's own promise.
            schedule(Arc::as_ptr(&task).cast_mut());
        }
    }
}

unsafe extern "C" fn tyrus_async_task_result_settled(context: *mut c_void) {
    unsafe {
        let task = Arc::from_raw(context.cast::<TyrusAsyncTask>());
        schedule(Arc::as_ptr(&task).cast_mut());
    }
}

struct TaskDependencyWake {
    task: Weak<TyrusAsyncTask>,
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn tyrus_async_task_await(
    task: *mut TyrusAsyncTask,
    dependency: *mut TyrusPromise,
) {
    unsafe {
        let task_ref = task_ref(task);
        task_ref.set_dependency(dependency);
        if crate::tyrus_promise_cancel_requested(task_ref.result) == 1
            && !task_ref.interrupted.swap(true, Ordering::AcqRel)
        {
            crate::tyrus_promise_request_cancel(
                dependency,
                TyrusString::literal("the awaiting task was cancelled"),
            );
        }
        Arc::increment_strong_count(task);
        let task_owner = Arc::from_raw(task);
        let context = Box::new(TaskDependencyWake {
            task: Arc::downgrade(&task_owner),
        });
        drop(task_owner);
        tyrus_promise_on_settle(
            dependency,
            Some(tyrus_async_task_wake),
            Box::into_raw(context).cast(),
        );
    }
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn tyrus_async_task_schedule(task: *mut TyrusAsyncTask) {
    schedule(task);
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn tyrus_async_task_wake(context: *mut c_void) {
    unsafe {
        let context = Box::from_raw(context.cast::<TaskDependencyWake>());
        let Some(task) = context.task.upgrade() else {
            return;
        };
        let dependency = task.take_dependency();
        if !dependency.is_null() {
            tyrus_promise_free(dependency);
        }
        schedule(Arc::as_ptr(&task).cast_mut());
    }
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn tyrus_async_task_free(task: *mut TyrusAsyncTask) {
    unsafe {
        if !task.is_null() {
            Arc::decrement_strong_count(task);
        }
    }
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn tyrus_async_block_on(promise: *mut TyrusPromise) -> i32 {
    unsafe {
        let state = wait_until_settled(promise);
        if state == TYRUS_PROMISE_FULFILLED {
            0
        } else {
            let message = crate::tyrus_promise_error_message(promise);
            let code = crate::tyrus_promise_error_code(promise);
            match (message.is_null(), code.is_null()) {
                (true, _) => eprintln!("tyrus asynchronous operation failed with state {state}"),
                (false, true) => eprintln!("{}", { message.as_str() }),
                (false, false) => eprintln!("{}: {}", { code.as_str() }, { message.as_str() }),
            }
            state
        }
    }
}

#[unsafe(no_mangle)]
pub extern "C" fn tyrus_task_sleep_async(milliseconds: u64) -> *mut TyrusPromise {
    let promise = crate::tyrus_promise_pending();
    unsafe { crate::tyrus_promise_retain(promise) };
    let owner = PromiseTaskOwner {
        promise: promise as usize,
    };
    executor().spawn(async move {
        tokio::time::sleep(std::time::Duration::from_millis(milliseconds)).await;
        unsafe { owner.fulfill_void() };
    });
    promise
}

#[unsafe(no_mangle)]
pub extern "C" fn tyrus_sleep(milliseconds: u64) {
    std::thread::sleep(std::time::Duration::from_millis(milliseconds));
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn tyrus_task_cancel(
    promise: *mut TyrusPromise,
    reason: TyrusString,
    grace_millis: u64,
) -> i32 {
    unsafe {
        let started = crate::tyrus_promise_request_cancel(promise, reason);
        if started == 0 || grace_millis == u64::MAX {
            return started;
        }
        crate::tyrus_promise_retain(promise);
        let address = promise as usize;
        executor().spawn(async move {
            tokio::time::sleep(std::time::Duration::from_millis(grace_millis)).await;
            let promise = address as *mut TyrusPromise;
            crate::tyrus_promise_cancel_pending(
                promise,
                TyrusString::literal("cancellation cleanup exceeded its deadline"),
            );
            crate::tyrus_promise_free(promise);
        });
        started
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{tyrus_promise_fulfill, tyrus_promise_pending, tyrus_promise_state};
    use std::sync::atomic::{AtomicUsize, Ordering};

    struct Frame {
        polls: AtomicUsize,
    }

    struct AwaitFrame {
        polls: AtomicUsize,
        dependency: *mut TyrusPromise,
    }

    struct CancelFrame {
        polls: Arc<AtomicUsize>,
        drops: Arc<AtomicUsize>,
        dependency: *mut TyrusPromise,
    }

    unsafe extern "C" fn poll_once(
        frame: *mut c_void,
        result: *mut TyrusPromise,
        _task: *mut TyrusAsyncTask,
    ) -> i32 {
        unsafe {
            let frame = &*frame.cast::<Frame>();
            frame.polls.fetch_add(1, Ordering::SeqCst);
            tyrus_promise_fulfill(result, std::ptr::null_mut(), None);
            TYRUS_ASYNC_READY
        }
    }

    unsafe extern "C" fn drop_frame(frame: *mut c_void) {
        unsafe {
            drop(Box::from_raw(frame.cast::<Frame>()));
        }
    }

    unsafe extern "C" fn poll_awaited(
        frame: *mut c_void,
        result: *mut TyrusPromise,
        task: *mut TyrusAsyncTask,
    ) -> i32 {
        unsafe {
            let frame = &*frame.cast::<AwaitFrame>();
            if frame.polls.fetch_add(1, Ordering::SeqCst) == 0 {
                tyrus_async_task_await(task, frame.dependency);
                return TYRUS_ASYNC_PENDING;
            }
            tyrus_promise_fulfill(result, std::ptr::null_mut(), None);
            TYRUS_ASYNC_READY
        }
    }

    unsafe extern "C" fn drop_await_frame(frame: *mut c_void) {
        unsafe {
            drop(Box::from_raw(frame.cast::<AwaitFrame>()));
        }
    }

    unsafe extern "C" fn poll_cancelled(
        frame: *mut c_void,
        _result: *mut TyrusPromise,
        task: *mut TyrusAsyncTask,
    ) -> i32 {
        unsafe {
            let frame = &*frame.cast::<CancelFrame>();
            frame.polls.fetch_add(1, Ordering::SeqCst);
            tyrus_async_task_await(task, frame.dependency);
            TYRUS_ASYNC_PENDING
        }
    }

    unsafe extern "C" fn drop_cancel_frame(frame: *mut c_void) {
        unsafe {
            let frame = Box::from_raw(frame.cast::<CancelFrame>());
            frame.drops.fetch_add(1, Ordering::SeqCst);
        }
    }

    #[test]
    fn tokio_executor_polls_a_generated_frame_and_settles_its_result() {
        let result = tyrus_promise_pending();
        let frame = Box::into_raw(Box::new(Frame {
            polls: AtomicUsize::new(0),
        }));
        unsafe {
            let task = tyrus_async_task_new(poll_once, Some(drop_frame), frame.cast(), result);
            tyrus_async_task_schedule(task);
            assert_eq!(tyrus_async_block_on(result), 0);
            assert_eq!(tyrus_promise_state(result), TYRUS_PROMISE_FULFILLED);
            assert_eq!((*frame).polls.load(Ordering::SeqCst), 1);
            tyrus_async_task_free(task);
            tyrus_promise_free(result);
        }
    }

    #[test]
    fn awaited_promise_wakes_and_reschedules_a_pending_frame() {
        let dependency = tyrus_promise_pending();
        let result = tyrus_promise_pending();
        let frame = Box::into_raw(Box::new(AwaitFrame {
            polls: AtomicUsize::new(0),
            dependency,
        }));
        unsafe {
            let task =
                tyrus_async_task_new(poll_awaited, Some(drop_await_frame), frame.cast(), result);
            tyrus_async_task_schedule(task);

            while (*frame).polls.load(Ordering::Acquire) == 0 {
                std::thread::yield_now();
            }
            assert_eq!(
                tyrus_promise_fulfill(dependency, std::ptr::null_mut(), None),
                1
            );
            assert_eq!(tyrus_async_block_on(result), 0);
            assert_eq!((*frame).polls.load(Ordering::SeqCst), 2);

            tyrus_async_task_free(task);
            tyrus_promise_free(result);
            tyrus_promise_free(dependency);
        }
    }

    #[test]
    fn cancelling_a_pending_result_drops_its_frame_without_waiting_for_the_dependency() {
        let dependency = tyrus_promise_pending();
        let result = tyrus_promise_pending();
        let polls = Arc::new(AtomicUsize::new(0));
        let drops = Arc::new(AtomicUsize::new(0));
        let frame = Box::into_raw(Box::new(CancelFrame {
            polls: polls.clone(),
            drops: drops.clone(),
            dependency,
        }));
        unsafe {
            let task = tyrus_async_task_new(
                poll_cancelled,
                Some(drop_cancel_frame),
                frame.cast(),
                result,
            );
            tyrus_async_task_schedule(task);
            tyrus_async_task_free(task);
            while polls.load(Ordering::Acquire) == 0 {
                std::thread::yield_now();
            }
            assert_eq!(
                tyrus_promise_cancel_pending(result, TyrusString::literal("test cancellation")),
                1
            );
            let deadline = std::time::Instant::now() + std::time::Duration::from_secs(1);
            while drops.load(Ordering::Acquire) == 0 && std::time::Instant::now() < deadline {
                std::thread::yield_now();
            }
            assert_eq!(drops.load(Ordering::SeqCst), 1);
            assert_eq!(
                tyrus_promise_state(dependency),
                crate::TYRUS_PROMISE_CANCELLED
            );
            tyrus_promise_free(result);
            tyrus_promise_free(dependency);
        }
    }

    #[test]
    fn task_sleep_async_is_pending_before_settling_without_blocking_the_caller() {
        let started = std::time::Instant::now();
        let promise = tyrus_task_sleep_async(20);
        assert!(started.elapsed() < std::time::Duration::from_millis(15));
        unsafe {
            assert_eq!(
                crate::tyrus_promise_state(promise),
                crate::TYRUS_PROMISE_PENDING
            );
            assert_eq!(tyrus_async_block_on(promise), 0);
            assert!(started.elapsed() >= std::time::Duration::from_millis(15));
            crate::tyrus_promise_free(promise);
        }
    }

    #[test]
    fn task_sleep_async_keeps_the_promise_alive_after_the_caller_releases_it() {
        let promise = tyrus_task_sleep_async(1);
        unsafe { crate::tyrus_promise_free(promise) };
        std::thread::sleep(std::time::Duration::from_millis(20));
    }

    #[test]
    fn sleep_blocks_the_current_thread() {
        for milliseconds in [0, 1, 10, 500] {
            let started = std::time::Instant::now();
            tyrus_sleep(milliseconds);
            assert!(
                started.elapsed() >= std::time::Duration::from_millis(milliseconds),
                "sleep({milliseconds}) returned before its requested delay"
            );
        }
    }

    #[test]
    fn public_task_cancellation_settles_once_and_preserves_the_reason() {
        let promise = tyrus_promise_pending();
        unsafe {
            assert_eq!(
                tyrus_task_cancel(
                    promise,
                    TyrusString::literal("Cancelled by caller"),
                    u64::MAX
                ),
                1
            );
            assert_eq!(
                tyrus_task_cancel(promise, TyrusString::literal("Ignored"), u64::MAX),
                0
            );
            assert_eq!(
                crate::tyrus_promise_state(promise),
                crate::TYRUS_PROMISE_CANCELLED
            );
            assert_eq!(
                crate::tyrus_promise_error_message(promise).as_str(),
                "Cancelled by caller"
            );
            crate::tyrus_promise_free(promise);
        }
    }
}
